import pandas as pd

def find_loyal_customers(customers: pd.DataFrame, purchases: pd.DataFrame) -> pd.DataFrame:
    if customers.empty or purchases.empty:
        return pd.DataFrame(columns=['customer_id', 'customer_name', 'active_months', 'total_spent'])

    purchases['ym'] = pd.to_datetime(purchases['purchase_date']).dt.strftime('%Y-%m')
    merged = pd.merge(customers, purchases, on='customer_id')

    agg = merged.groupby(['customer_id', 'customer_name']).agg(
        active_months=('ym', 'nunique'),
        total_spent=('amount', 'sum')
    ).reset_index()

    res = agg[(agg['active_months'] >= 3) & (agg['total_spent'] >= 500.00)]
    return res.sort_values(by='customer_id', ascending=True)
